        best_score = None
        for c in corners:
            score = dist(c, opp_pos)
            if best_score is None or score > best_score:
                best_score = score
                target = c
        return clamp_move(target[0] - sx, target[1] - sy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory") or []
        if not targets:
            return clamp_move(ox - sx, oy - sy)
        best = None
        best_score = None
        for t in targets:
            tx, ty = pos(t, self_pos)
            score = dist(self_pos, (tx, ty)) * 2 - dist(opp_pos, (tx, ty))
            if best_score is None or score < best_score:
                best_score = score
                best = (tx, ty)
        return clamp_move(best[0] - sx, best[1] - sy)

    resources = observation.get("resources") or []
    if resources:
        best = None
        best_score = None
        for r in resources:
            rx, ry = pos(r, self_pos)
            score = dist(self_pos, (rx, ry)) * 2 - dist(opp_pos, (rx, ry))
            if best_score is None or score < best_score:
                best_score = score
                best = (rx, ry)
        return clamp_move(best[0] - sx, best[1] - sy)

    return clamp_move(ox - sx, oy - sy)

